    if(manifest.kind === 'Error') {
        panic(manifest.message);
    }
    const count = args.includes('--count');
    let total = 0;
    let index = 0;
    for(const row of manifest.text.split('\n')) {
        if(row === '') {
            continue;
        }
        if(!count) {
            console.log(`case ${index}`);
        }
        total += run(row, count);
        index++;
    }
    if(count) {
        console.log(`${total}`);
    }
}
else {
    run(first, false);
}

