import type { Context } from './context.a';
import { messageOctalEscape } from './messages.a';
export function noOctalEscape(context: Context, index: number): void {
    if(!context.enabled('no-octal-escape')) {
        return;
    }
    if(context.kind(index) !== 'StringLiteral') {
        return;
    }
    const raw = context.raw(index);
    for(let position = 0; position < raw.length; position++) {
        if(raw.slice(position, position + 1) !== '\\') {
            continue;
        }
        const start = position + 1;
        const first = raw.slice(start, start + 1);
        let width = 0;
        if(first >= '0' && first <= '3') {
            width = 1;
            while(
                width < 3 &&
                raw.slice(start + width, start + width + 1) >= '0' &&
                raw.slice(start + width, start + width + 1) <= '7'
            ) {
                width++;
            }
            if(width < 2) {
                width = 0;
            }
